import { formatPrice } from '../utils'

type CartItem = { id: number; name: string; price: number }
type CartProps = { items: CartItem[] }

export function Cart({ items }: CartProps) {
  return (
    <ul>
      {items.map(item => (
        <li key={item.id}>
          {item.name} <span>formatPrice(item.price)</span>
        </li>
      ))}
    </ul>
  )
}
